// Get synthesizer output
let synthesizerOutput = $input.first().json;

// Handle if output is an array
if (Array.isArray(synthesizerOutput) && synthesizerOutput.length > 0) {
  synthesizerOutput = synthesizerOutput[0];
}

let synthesizedReport = '';

// Validate synthesizer output structure
if (synthesizerOutput && synthesizerOutput.message && synthesizerOutput.message.content) {
  synthesizedReport = synthesizerOutput.message.content;
} else if (synthesizerOutput && synthesizerOutput.choices && synthesizerOutput.choices[0] && synthesizerOutput.choices[0].message) {
  synthesizedReport = synthesizerOutput.choices[0].message.content;
}

// Get user context data from Extract Form Data node
const formData = $('Extract Form Data').first().json;

// Extract sections
const extractSection = (patterns) => {
  if (!synthesizedReport) {
    return '';
  }

  for (const pattern of patterns) {
    const match = synthesizedReport.match(pattern);
    if (match && match[1] && match[1].trim().length > 10) {
      return match[1].trim();
    }
  }
  return '';
};

// Calculate confidence score from HHH values
const calculateConfidenceScore = () => {
  if (!synthesizedReport) return '';

  // Extract HHH average scores for each agent
  const extractHHH = (agentName) => {
    const pattern = new RegExp(agentName + ':\\s*\\[Helpful:\\s*(\\d+)\\s*\\|\\s*Harmless:\\s*(\\d+)\\s*\\|\\s*Honest:\\s*(\\d+)\\]\\s*=\\s*Avg:\\s*(\\d+\\.?\\d*)', 'i');
    const match = synthesizedReport.match(pattern);

    if (match && match[4]) {
      return parseFloat(match[4]);
    }
    return 0;
  };

  const scores = {
    marketData: extractHHH('Market Data Analysis'),
    marketIntel: extractHHH('Market Intelligence'),
    strategic: extractHHH('Strategic Analysis'),
    risk: extractHHH('Risk Management'),
    competitive: extractHHH('Competitive Analysis')
  };

  console.log('Extracted HHH scores:', scores);

  // Calculate base score using weighted formula
  const baseScore = (scores.marketData * 0.25) + 
                    (scores.marketIntel * 0.25) + 
                    (scores.strategic * 0.20) + 
                    (scores.risk * 0.15) + 
                    (scores.competitive * 0.15);

  console.log('Base score:', baseScore);

  // Extract adjustment from agent's Step 2
  let adjustment = 0;

  if (synthesizedReport.match(/Selected adjustment:\\s*\\+8%/i) || 
      synthesizedReport.match(/Strong.*?agreement.*?\\+8%/i)) {
    adjustment = 8;
  } else if (synthesizedReport.match(/Selected adjustment:\\s*-7%/i) || 
             synthesizedReport.match(/Major conflicts.*?-7%/i)) {
    adjustment = -7;
  } else if (synthesizedReport.match(/Selected adjustment:\\s*0%/i) ||
             synthesizedReport.match(/Moderate agreement.*?0%/i)) {
    adjustment = 0;
  }

  console.log('Adjustment:', adjustment);

  // Calculate final confidence score
  const finalScore = baseScore + adjustment;

  console.log('Final confidence score:', finalScore);

  if (isNaN(finalScore)) {
    return '';
  }

  return finalScore.toFixed(2);
};

// Build output with calculated confidence score
return {
  json: {
    report_id: 'RPT-' + Date.now(),
    timestamp: new Date().toISOString(),
    user_email: formData.user_email,
    company_name: formData.company_name,
    job_function: formData.job_function,
    strategic_question: formData.strategic_question,
    confidence_score: calculateConfidenceScore(),
    pdf_included: formData.pdf_processed,
    full_report: synthesizedReport,
    executive_summary: extractSection([/### EXECUTIVE SUMMARY([\s\S]*?)(?=###|$)/i, /### INTEGRATED ANALYSIS SUMMARY([\s\S]*?)(?=###|$)/i]),
    market_comparison: extractSection([/### DETAILED MARKET COMPARISON TABLE([\s\S]*?)(?=###|$)/i]),
    cross_validation: extractSection([/### CROSS-VALIDATION TABLE([\s\S]*?)(?=###|$)/i]),
    strategic_insights: extractSection([/### STRATEGIC INSIGHTS([\s\S]*?)(?=###|$)/i]),
    decision_factors: extractSection([/### TOP 3 DECISION FACTORS([\s\S]*?)(?=###|$)/i]),
    recommendations: extractSection([/### STRATEGIC RECOMMENDATIONS([\s\S]*?)(?=###|$)/i]),
    risk_matrix: extractSection([/### RISK\/OPPORTUNITY MATRIX([\s\S]*?)(?=###|$)/i]),
    executive_framework: extractSection([/### EXECUTIVE DECISION FRAMEWORK([\s\S]*?)(?=###|$)/i]),
    limitations: extractSection([/### LIMITATIONS & FOLLOW-UP([\s\S]*?)(?=###|$)/i]),
    reliability: extractSection([/### AGENT RELIABILITY ASSESSMENT([\s\S]*?)$/i]),
    ai_chip_rate: formData.user_ai_chip_rate,
    crypto_rate: formData.user_crypto_rate,
    ev_rate: formData.user_ev_rate,
    supply_risk: formData.user_supply_risk,
    regulatory: formData.user_regulatory,
    consumer_rate: formData.user_consumer_rate,
    session_id: formData.session_id
  }
};

